fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() - 1;

    while left <= right {
        let mid = left + (right - left) / 2;
        let mid_val = v[mid];

        if mid_val == k {
            return mid;
        } else if mid_val < k {
            left = mid + 1;
        } else {
            // mid_val > k
            // Since k appears at least once, it must be in the left half now
            if mid == 0 {
                break; // to avoid underflow
            }
            right = mid - 1;
        }
    }

    // According to the problem's assumption k always exists,
    // so this point should not be reached.
    // But to satisfy Rust’s type checker, we return 0 here.
    0
}